<?php
namespace Modules\PriyasaCore\Http\Controllers\Storefront;
use Illuminate\Http\Request; use Modules\PriyasaCore\Http\Controllers\Controller; use Modules\PriyasaCore\Models\Order; use Modules\PriyasaCore\Services\{CustomerResolver,PostOrderLifecycleService};
class PostOrderController extends Controller { public function eligibility(Request $r, Order $order){$c=app(CustomerResolver::class)->resolve($r);abort_unless((int)$order->customer_id===(int)$c->id,403);return response()->json(app(PostOrderLifecycleService::class)->eligibility($order->load('items')));} public function cancel(Request $r, Order $order){$c=app(CustomerResolver::class)->resolve($r);abort_unless((int)$order->customer_id===(int)$c->id,403);return response()->json(app(PostOrderLifecycleService::class)->cancel($order,'customer',(string)$c->id));} public function return(Request $r, Order $order){$c=app(CustomerResolver::class)->resolve($r);abort_unless((int)$order->customer_id===(int)$c->id,403);$data=$r->validate(['reason'=>'required|string|max:255','items'=>'required|array|min:1','items.*.order_item_id'=>'required|integer','items.*.quantity'=>'required|integer|min:1']);return response()->json(app(PostOrderLifecycleService::class)->requestReturn($order,$data['items'],$data['reason'],(string)$c->id),201);} }
